<script setup lang="ts">
import{nextTick,onBeforeUnmount,onMounted,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{agentApi}from'@/api/agent';import{knowledgeApi}from'@/api/knowledge'
const route=useRoute(),router=useRouter(),conversations=ref<any[]>([]),active=ref<any>(),prompt=ref(''),streaming=ref(false),draft=ref(''),tools=ref<any[]>([]),citation=ref<any>(),messagesEl=ref<HTMLElement>(),useFavorites=ref(false),knowledgeBases=ref<any[]>([]),selectedKnowledge=ref<string[]>([]);let connection:any
const quick=['总结今天 AI 行业','分析这个事件的核心变化','比较主要观点','预测后续趋势'];async function loadList(){conversations.value=await agentApi.list()}async function open(id:string){active.value=await agentApi.detail(id);await router.replace({query:{conversation:id}});await scroll()}async function create(){const c=await agentApi.create({title:'新会话',event_id:route.query.event_id||null,context_config:{source:route.query.event_id?'event':'manual'}});await loadList();await open(c.id)}async function send(){const text=prompt.value.trim();if(!text||streaming.value)return;active.value.messages.push({id:Date.now(),role:'user',content:text,citations:[]});prompt.value='';draft.value='';tools.value=[];streaming.value=true;connection=agentApi.send(active.value.id,{content:text,context_additions:useFavorites.value?[{type:'favorite'}]:[],knowledge_base_ids:selectedKnowledge.value},async(t,d)=>{if(t==='message.delta')draft.value+=d.text;if(t==='tool.started')tools.value.push({...d,status:'running'});if(t==='tool.completed'){const x=[...tools.value].reverse().find((v:any)=>v.name===d.name);if(x)Object.assign(x,d,{status:'completed'})}if(t==='message.completed'){active.value.messages.push(d);draft.value='';streaming.value=false;await loadList()}if(t==='message.failed'){draft.value=d.message;streaming.value=false}await scroll()})}function stop(){connection?.close();streaming.value=false;draft.value=''}async function scroll(){await nextTick();messagesEl.value?.scrollTo({top:messagesEl.value.scrollHeight})}async function remove(id:string){await agentApi.remove(id);if(active.value?.id===id)active.value=null;await loadList();if(!active.value)await create()}onMounted(async()=>{knowledgeBases.value=await knowledgeApi.bases();await loadList();const id=String(route.query.conversation||'');if(id)await open(id);else await create()});onBeforeUnmount(stop)
</script>
<template><main class="agent"><aside><header><strong>InfoPulse Agent</strong><button title="新建会话" @click="create">＋</button></header><nav><button v-for="c in conversations" :key="c.id" :class="{active:active?.id===c.id}" @click="open(c.id)"><span>{{c.title}}</span><small>{{c.event_id?'固定事件':'自由对话'}}</small><i @click.stop="remove(c.id)">×</i></button></nav></aside><section class="chat"><header><div><small>AI AGENT</small><h1>{{active?.title||'新会话'}}</h1></div><span v-if="active?.event_id">事件上下文已固定</span></header><div ref="messagesEl" class="messages"><section v-if="!active?.messages?.length" class="welcome"><h2>今天需要分析什么？</h2><button v-for="q in quick" :key="q" @click="prompt=q">{{q}}</button></section><article v-for="m in active?.messages" :key="m.id" :class="m.role"><div><small>{{m.role==='user'?'YOU':'INFOPULSE'}}</small><p>{{m.content}}</p><footer v-if="m.citations?.length"><button v-for="c in m.citations" :key="c.id" @click="citation=c">{{c.citation_type==='private'?'私有知识':'公开来源'}} · {{c.source}}</button></footer><div v-if="m.role==='assistant'" class="feedback"><button @click="agentApi.feedback(active.id,m.id,'up')">有帮助</button><button @click="agentApi.feedback(active.id,m.id,'down')">需改进</button></div></div></article><div v-if="tools.length" class="tools"><div v-for="t in tools" :key="t.name"><span>{{t.status==='completed'?'✓':'…'}}</span>{{t.name==='search'?'正在搜索公开情报':t.name==='knowledge_base'?'正在检索私有知识':'正在读取事件上下文'}}<small v-if="t.count!==undefined">{{t.count}} 条证据</small></div></div><article v-if="draft" class="assistant"><div><small>INFOPULSE · STREAMING</small><p>{{draft}}</p></div></article></div><footer class="composer"><textarea v-model="prompt" rows="2" placeholder="输入问题，Agent 会展示搜索、读取与引用过程" @keydown.ctrl.enter="send"/><div><span><label><input v-model="useFavorites" type="checkbox"/> 收藏上下文</label><select v-model="selectedKnowledge" multiple title="选择知识库"><option v-for="b in knowledgeBases" :key="b.id" :value="b.id">{{b.name}}</option></select></span><button v-if="streaming" @click="stop">停止</button><button v-else @click="send">发送</button></div></footer></section><el-drawer v-model="citation" title="回答引用" size="min(480px,92%)"><template v-if="citation"><h3>{{citation.title}}</h3><p><b>{{citation.citation_type==='private'?'私有知识':'公开来源'}}</b> · {{citation.source}}</p><blockquote>{{citation.quote}}</blockquote><p v-if="citation.citation_type==='private'">{{citation.page?`第 ${citation.page} 页`:''}} {{citation.paragraph?`第 ${citation.paragraph} 段`:''}}</p><a v-else :href="citation.url" target="_blank">打开原文</a></template></el-drawer></main></template>
<style scoped>.agent{height:100vh;display:grid;grid-template-columns:250px 1fr;background:#f3f5f4;color:#17231f}.agent>aside{padding:18px 12px;border-right:1px solid #d4ddda;background:#fff}.agent>aside header{display:flex;justify-content:space-between;align-items:center;padding:0 6px 16px}.agent button{cursor:pointer}.agent nav{display:grid;gap:4px}.agent nav button{position:relative;padding:10px;border:0;border-radius:5px;display:grid;text-align:left;background:transparent}.agent nav button.active{background:#e8f2ef}.agent nav small{color:#7a8b85}.agent nav i{position:absolute;right:8px}.chat{min-width:0;display:grid;grid-template-rows:68px 1fr auto}.chat>header{padding:0 28px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #d4ddda;background:#fff}.chat h1{margin:3px 0;font-size:19px}.chat header small{color:#188178}.messages{overflow:auto;padding:28px max(20px,calc((100% - 840px)/2))}.messages article{margin-bottom:18px;display:flex}.messages article>div{max-width:780px;padding:16px 18px;border:1px solid #d4ddda;border-radius:7px;background:white}.messages article.user{justify-content:flex-end}.messages article.user>div{color:white;background:#19302a}.messages p{white-space:pre-wrap;line-height:1.7}.messages footer button,.feedback button{margin-right:6px;border:0;color:#16776e;background:#e8f3f0}.feedback{margin-top:12px}.tools{margin:10px 0;padding:12px;border-left:2px solid #178078;background:#edf4f2}.tools div{padding:5px}.tools span{margin-right:8px}.welcome{padding-top:12vh;text-align:center}.welcome h2{font:650 34px Georgia,serif}.welcome button{margin:4px;padding:10px;border:1px solid #ccd7d2;background:white}.composer{margin:0 auto 18px;width:min(840px,calc(100% - 28px));padding:10px;border:1px solid #bfcfc9;border-radius:7px;background:white}.composer textarea{width:100%;resize:none;border:0;outline:0}.composer>div{display:flex;justify-content:space-between;align-items:end;color:#84938e;font-size:11px}.composer select{margin-left:10px;max-width:190px;height:38px;border:1px solid #ccd7d2}.composer button{padding:7px 13px;border:0;border-radius:4px;color:white;background:#17312a}blockquote{padding:14px;border-left:3px solid #178078;background:#edf4f2}@media(max-width:720px){.agent{height:calc(100vh - 64px);grid-template-columns:1fr}.agent>aside{display:none}.chat>header{padding:0 16px}.messages{padding:18px 12px}.composer select{max-width:130px}.welcome h2{font-size:27px}}</style>
